//! # Facade wiring — security and OpenAPI reachable through `aether`
//!
//! Four claims, one per behaviour: a JWT verifies through the facade, the constant-time
//! comparison and the desync audit are callable from it, and an OpenAPI document is generated by
//! it. Every path below starts at `aether::`, so the test fails to compile if the facade stops
//! re-exporting any of them — which is the entire point: these crates existed and nothing named
//! them from the crate a user actually depends on.
//!
//! The token is precomputed with the documented HS256 construction (RFC 7519 §3.1) so the test
//! needs no signer of its own: a signature the test can mint is a signature the test can get
//! wrong the same way the verifier does.

use aether::header::{HeaderMap, HeaderView};
use aether::{AetherError, JwtValidationOptions, JwtValidator};

const SECRET: &[u8] = b"super-secret-key-1234567890-aether";

/// `{"alg":"HS256","typ":"JWT"}` . `{"sub":"1234567890","name":"Hamza"}`, HMAC-SHA256 with
/// [`SECRET`].
const TOKEN: &str = concat!(
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.",
    "eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkhhbXphIn0.",
    "ateqwQML6mXum1yhLglZHx8o0vTtfrp37k0vEcfczbQ"
);

/// The same header and payload, signed with a different key: the signature cannot verify.
const WRONG_KEY_TOKEN: &str = concat!(
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.",
    "eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkhhbXphIn0.",
    "qzHeH0DgEoORH9dRL8vSCmVRqXepS7F0CSBVLkD_alY"
);

fn headers(pairs: &[(&'static str, &'static [u8])]) -> HeaderMap<'static> {
    HeaderMap::from_vec(
        pairs
            .iter()
            .map(|(name, value)| HeaderView { name, value })
            .collect(),
    )
}

#[test]
fn a_jwt_verifies_through_the_facade() {
    let validator = JwtValidator::new(SECRET);
    let options = JwtValidationOptions {
        now_unix: Some(1_000),
        ..JwtValidationOptions::default()
    };

    let verified = validator
        .verify(TOKEN, &options)
        .expect("the precomputed token is well formed and correctly signed");
    assert_eq!(verified.claims["sub"], "1234567890");
    assert_eq!(verified.claims["name"], "Hamza");

    assert!(
        validator.verify(WRONG_KEY_TOKEN, &options).is_err(),
        "a token signed with another key must not verify"
    );

    assert!(
        validator.verify(&format!("{TOKEN}="), &options).is_err(),
        "a padded signature is one credential under a second spelling, not a token to admit"
    );
}

#[test]
fn constant_time_comparison_is_reachable_through_the_facade() {
    assert!(aether::constant_time_eq(b"secret123", b"secret123"));
    assert!(!aether::constant_time_eq(b"secret123", b"secret124"));
    assert!(
        !aether::security::constant_time_eq(b"secret123", b"secret12"),
        "a prefix is not equal; the module path must name the same function"
    );
}

#[test]
fn the_desync_audit_rejects_conflicting_framing_through_the_facade() {
    let plain = headers(&[("host", b"localhost"), ("accept", b"*/*")]);
    assert!(
        aether::audit_request_desync(&plain).is_ok(),
        "unambiguous framing is not a desync"
    );

    let cl_and_te = headers(&[
        ("content-length", &b"5"[..]),
        ("transfer-encoding", &b"chunked"[..]),
    ]);
    assert!(matches!(
        aether::audit_request_desync(&cl_and_te),
        Err(AetherError::MalformedRequest)
    ));

    let dual_cl = headers(&[("content-length", &b"5"[..]), ("content-length", &b"6"[..])]);
    assert!(
        matches!(
            aether::security::audit_request_desync(&dual_cl),
            Err(AetherError::MalformedRequest)
        ),
        "two Content-Length fields leave the request's end undecidable"
    );

    let non_chunked = headers(&[("transfer-encoding", &b"gzip"[..])]);
    assert!(
        matches!(
            aether::audit_request_desync(&non_chunked),
            Err(AetherError::MalformedRequest)
        ),
        "only a single `chunked` coding frames a body"
    );

    let dual_te = headers(&[
        ("transfer-encoding", &b"chunked"[..]),
        ("transfer-encoding", &b"chunked"[..]),
    ]);
    assert!(
        matches!(
            aether::audit_request_desync(&dual_te),
            Err(AetherError::MalformedRequest)
        ),
        "two Transfer-Encoding fields are refused, not merged"
    );
}

#[test]
fn an_openapi_document_is_generated_through_the_facade() {
    use aether::openapi::{OpenApiSpec, Operation, PathItem, ResponseSpec};
    use std::collections::BTreeMap;

    let mut spec = OpenApiSpec::new("Aether", "1.0.0");
    spec.paths.insert(
        "/health".to_string(),
        PathItem {
            methods: BTreeMap::from([(
                "get".to_string(),
                Operation {
                    summary: "Health check".to_string(),
                    operation_id: "health".to_string(),
                    parameters: Vec::new(),
                    responses: BTreeMap::from([(
                        "200".to_string(),
                        ResponseSpec {
                            description: "healthy".to_string(),
                        },
                    )]),
                },
            )]),
        },
    );

    let json = spec.to_json().expect("the spec serialises as JSON");
    assert!(json.contains("\"openapi\": \"3.1.0\""), "{json}");
    assert!(json.contains("\"title\": \"Aether\""), "{json}");
    assert!(json.contains("\"operationId\": \"health\""), "{json}");
    assert!(
        json.contains("\"get\": {"),
        "a path item is keyed by the verb, which is what a consumer reads: {json}"
    );
}
